import{_ as r,o as t,c as l,a3 as u,j as e,a as n}from"./chunks/framework.z_KJ15Ep.js";const o="/bilder/berufskolleg/gruppenprozesse-bk-gruppe-bk-vorlaeufige-abschlussnoten.png",f=JSON.parse('{"title":"Vorläufige BK-Abschlussnoten berechnen","description":"","frontmatter":{"title":"Vorläufige BK-Abschlussnoten berechnen","source_pageid":1333,"source_revision":4905},"headers":[],"relativePath":"zeugnisse/berufskolleg/vorlaeufige-abschlussnoten-berechnen-gruppenprozesse-bk-abschluss.md","filePath":"zeugnisse/berufskolleg/vorlaeufige-abschlussnoten-berechnen-gruppenprozesse-bk-abschluss.md"}'),i={name:"zeugnisse/berufskolleg/vorlaeufige-abschlussnoten-berechnen-gruppenprozesse-bk-abschluss.md"};function a(c,s,h,d,b,g){return t(),l("div",null,[...s[0]||(s[0]=[u('<h1 id="vorlaufige-bk-abschlussnoten-berechnen" tabindex="-1">Vorläufige BK-Abschlussnoten berechnen <a class="header-anchor" href="#vorlaufige-bk-abschlussnoten-berechnen" aria-label="Permalink to &quot;Vorläufige BK-Abschlussnoten berechnen&quot;">​</a></h1><p>Ermitteln Sie Abschlussnoten aus den vorhandenen Leistungs- und Prüfungsdaten. Nicht eindeutig berechenbare Noten und die endgültige Festlegung bleiben bei den zuständigen Lehrkräften.</p><p><a href="/bilder/berufskolleg/gruppenprozesse-bk-gruppe-bk-vorlaeufige-abschlussnoten.png"><img src="'+o+'" alt="Je nach geltender Prüfungsordnung werden Abschlussnoten berechnet." loading="lazy"></a></p><p><em>Je nach geltender Prüfungsordnung werden Abschlussnoten berechnet.</em></p><p>Wenn bei einer ausgewählten Schülergruppe Abschlüsse und/oder Abschlussnoten vergeben werden, die aus schon eingetragenen Leistungsdaten oder Leistungsdaten und Prüfungsnoten ermittelt werden, können diese Abschlussnoten über den Gruppenprozess <em>BK-Abschluss</em> ➜ <strong>Vorläufige Abschlussnoten berechnen</strong> ermittelt werden.</p><p>Die Noten sind im Anschluss unter <em>Schüler ➜ BK-Abschluss</em> eingetragen.</p><p>Die Abschlussnoten sind endgültig durch die hierfür verantwortlichen Lehrkräfte entsprechend der für den Abschluss geltenden Vorgaben zu prüfen und endgültig festzulegen.</p><p>Manche Noten lassen sich nicht arithmetisch mitteln und sind daher trotz des Gruppenprozesses von Hand einzutragen.</p>',8),e("div",{"data-hint-kind":"example",class:"example custom-block"},[e("p",{class:"custom-block-title"},[e("svg",{class:"hint-icon","data-icon":"example","aria-hidden":"true",focusable:"false",viewBox:"0 0 24 24",fill:"none",stroke:"currentColor","stroke-width":"1.8","stroke-linecap":"round","stroke-linejoin":"round"},[e("path",{d:"M9 3h6m-5 0v6l-6 9a2 2 0 0 0 2 3h12a2 2 0 0 0 2-3l-6-9V3M7 15h10"})]),n("Beispiel")]),e("p",null,[n("Die sich aus "),e("em",null,"gut (2)"),n(" und "),e("em",null,"befriedigend (3)"),n(" ergebende Gesamtnote kann SchILD-NRW nicht automatisch bestimmen.")])],-1),e("hr",null,null,-1),e("p",null,[e("a",{href:"https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Vorl%C3%A4ufige_Abschlussnoten_berechnen_(Gruppenprozesse_BK-Abschluss)",target:"_blank",rel:"noreferrer"},"Originalartikel im Wiki"),n(" · Quellrevision 4905.")],-1)])])}const m=r(i,[["render",a]]);export{f as __pageData,m as default};
